def is_prime(n: int) -> bool:
    """Return whether ``n`` is prime.

    The function handles all non‑negative integers. ``0`` and ``1`` are
    considered non‑prime. ``2`` and ``3`` are prime. For larger numbers we
    perform trial division up to the integer square root.
    """
    if n < 2:
        return False
    if n in (2, 3):
        return True
    if n % 2 == 0:
        return False
    import math
    limit = int(math.isqrt(n))
    for d in range(3, limit + 1, 2):
        if n % d == 0:
            return False
    return True
